head.b:skin:
:root{--navy:#0f2a4a;--navy-2:#163a63;--teal:#0ea5a4;--teal-dark:#0b8584;--text:#1f2937;--muted:#6b7280;--line:#e5e7eb;--bg:#f7f8fa;--card:#fff;--radius:14px;--shadow:0 1px 2px rgba(16,24,40,.06),0 4px 16px rgba(16,24,40,.06)}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--text);font:17px/1.75 Inter,system-ui,-apple-system,"Segoe UI",sans-serif;-webkit-font-smoothing:antialiased}
a{color:var(--teal-dark);text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;height:auto}
.wrap{max-width:1160px;margin:0 auto;padding:0 20px}
.section{margin:0}.widget{margin:0}
.widget-title,.widget h3.title{font-size:13px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin:0 0 14px}

/* Header */
.site-header{background:var(--navy);color:#fff;position:sticky;top:0;z-index:50;box-shadow:0 2px 12px rgba(0,0,0,.15)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;gap:20px;min-height:68px;flex-wrap:wrap}
.site-header .Header h1,.site-header .Header .title{font-size:22px;font-weight:800;margin:0;letter-spacing:-.02em}
.site-header .Header a{color:#fff;text-decoration:none}
.site-header .header-widget h1::before{content:"";display:inline-block;width:12px;height:12px;border-radius:3px;background:var(--teal);margin-right:10px;transform:rotate(45deg)}
.site-header .Header .description,.site-header .header-widget p{display:none}
main{min-width:0}
.svg-icon-24,.svg-icon-18,.post-share-buttons svg,.byline svg{width:20px;height:20px;fill:currentColor;vertical-align:middle}
.post-share-buttons,.sharing,.share-button,.byline.post-share-buttons,.post-header-line-1 .byline.reactions{display:none!important}
.post-footer .byline{margin-right:14px}
.blog-feeds,.feed-links{display:none}
.site-nav ul{list-style:none;margin:0;padding:0;display:flex;gap:4px;flex-wrap:wrap}
.site-nav li a{display:block;padding:8px 14px;border-radius:8px;color:#dbe7f5;font-size:15px;font-weight:500}
.site-nav li a:hover{background:rgba(255,255,255,.1);color:#fff;text-decoration:none}
.footer-nav{display:flex;gap:18px;flex-wrap:wrap}
.site-nav .PageList ul{list-style:none;margin:0;padding:0;display:flex;gap:4px;flex-wrap:wrap}
.site-nav .PageList li a{display:block;padding:8px 14px;border-radius:8px;color:#dbe7f5;font-size:15px;font-weight:500}
.site-nav .PageList li a:hover,.site-nav .PageList li.selected a{background:rgba(255,255,255,.1);color:#fff;text-decoration:none}
.site-nav .widget-title,.site-nav h3.title{display:none}

/* Hero */
.hero{background:linear-gradient(135deg,var(--navy) 0%,var(--navy-2) 60%,#145b6a 100%);color:#fff;padding:64px 0 72px;text-align:center}
.hero h2{font-size:clamp(30px,5vw,48px);line-height:1.15;font-weight:800;letter-spacing:-.03em;margin:0 auto 16px;max-width:820px}
.hero h2 span{color:#5eead4}
.hero p{font-size:19px;color:#c7d6e8;max-width:640px;margin:0 auto 28px}
.hero .chips{display:flex;gap:10px;justify-content:center;flex-wrap:wrap}
.hero .chips a{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.2);color:#fff;padding:8px 16px;border-radius:999px;font-size:14px;font-weight:500}
.hero .chips a:hover{background:var(--teal);border-color:var(--teal);text-decoration:none}

/* Layout */
.main-wrap{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:40px;padding:48px 20px}
@media(max-width:960px){.main-wrap{grid-template-columns:1fr}}

/* Posts list */
.blog-posts{display:grid;gap:24px}
.is-multiple .blog-posts{grid-template-columns:repeat(auto-fill,minmax(300px,1fr))}
.post-outer-container{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);overflow:hidden;transition:transform .15s,box-shadow .15s}
.is-multiple .post-outer-container:hover{transform:translateY(-3px);box-shadow:0 10px 28px rgba(16,24,40,.12)}
.post-outer{padding:28px}
.is-single .post-outer{padding:44px clamp(20px,5vw,56px)}
.post-title{font-size:21px;line-height:1.3;font-weight:700;letter-spacing:-.01em;margin:0 0 10px}
.post-title a{color:var(--navy)}
.is-single .post-title{font-size:clamp(28px,4vw,40px);line-height:1.2;font-weight:800;color:var(--navy);margin-bottom:14px}
.post-header,.post-header-line-1,.byline{font-size:14px;color:var(--muted)}
.byline{display:inline-block;margin-right:12px}
.snippet-thumbnail,.post-snippet .snippet-thumbnail{margin:-28px -28px 18px;aspect-ratio:16/9;overflow:hidden;background:#e8eef5}
.snippet-thumbnail img,.snippet-thumbnail .snippet-thumbnail-img{width:100%;height:100%;object-fit:cover;background-size:cover;background-position:center}
.post-snippet,.snippet-item{color:#4b5563;font-size:16px}
.jump-link a,.snippet-fade + .jump-link a{display:inline-block;margin-top:12px;font-weight:600;color:var(--teal-dark)}
.post-labels,.post-footer{font-size:14px;color:var(--muted);margin-top:18px}
.post-labels a,.labels-outer-container a{display:inline-block;background:#ecfdf5;color:var(--teal-dark);padding:3px 10px;border-radius:999px;margin:2px 4px 2px 0;font-size:13px;font-weight:500}

/* Article body */
.post-body{font-size:18px;line-height:1.8;color:#273142}
.post-body h2{font-size:28px;line-height:1.3;color:var(--navy);margin:44px 0 14px;letter-spacing:-.02em}
.post-body h3{font-size:22px;color:var(--navy);margin:32px 0 10px}
.post-body p{margin:0 0 20px}
.post-body ul,.post-body ol{padding-left:24px;margin:0 0 22px}
.post-body li{margin:6px 0}
.post-body a{text-decoration:underline;text-underline-offset:3px}
.post-body blockquote{margin:28px 0;padding:18px 22px;border-left:4px solid var(--teal);background:#f0fdfa;border-radius:0 10px 10px 0;color:#134e4a}
.post-body table{width:100%;border-collapse:collapse;margin:24px 0;font-size:16px;display:block;overflow-x:auto}
.post-body th{background:var(--navy);color:#fff;text-align:left}
.post-body th,.post-body td{padding:10px 14px;border:1px solid var(--line)}
.post-body tr:nth-child(even) td{background:#f9fafb}
.post-body img{border-radius:10px}
.post-body code{background:#f1f5f9;padding:2px 6px;border-radius:6px;font-size:.9em}
.post-body pre{background:#0f172a;color:#e2e8f0;padding:18px;border-radius:10px;overflow:auto}

/* Pagination & comments */
.blog-pager{display:flex;justify-content:space-between;margin-top:32px}
.blog-pager a{background:var(--navy);color:#fff;padding:10px 20px;border-radius:10px;font-weight:600}
.blog-pager a:hover{background:var(--teal-dark);text-decoration:none}
.comments{margin-top:32px;background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:28px}
.comments h3.title{font-size:20px;color:var(--navy)}

/* Sidebar */
.sidebar .widget{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:22px;margin-bottom:22px;box-shadow:var(--shadow)}
.sidebar ul{list-style:none;margin:0;padding:0}
.sidebar .PopularPosts .post{display:flex;gap:12px;padding:10px 0;border-top:1px solid var(--line)}
.sidebar .PopularPosts .post:first-child{border-top:0;padding-top:0}
.sidebar .PopularPosts .post-title{font-size:15px;margin:0}
.sidebar .PopularPosts .snippet-item,.sidebar .PopularPosts .post-header{display:none}
.sidebar .PopularPosts img{width:72px;height:56px;object-fit:cover;border-radius:8px}
.BlogSearch form,.search-input{display:flex;gap:8px}
.BlogSearch input[type=text],.search-input input{flex:1;padding:10px 12px;border:1px solid var(--line);border-radius:10px;font:inherit;font-size:15px;min-width:0}
.BlogSearch input[type=submit],.search-action{background:var(--teal);color:#fff;border:0;border-radius:10px;padding:10px 14px;font-weight:600;cursor:pointer}
.search-input{flex:1;min-width:0}
.search-input input{width:100%;box-sizing:border-box}
.search-action{flex:none}
.sidebar .PopularPosts:not(:has(.post)){display:none}
.is-multiple .post-body>*:nth-child(n+3){display:none}
.is-multiple .post-body>p:nth-child(2){display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;margin:0}
.is-multiple .post-body>p:first-child{margin:0 0 14px}
.is-multiple .post-body>p:first-child img{display:block}
.ContactForm input[type=text],.ContactForm textarea,.contact-form-name,.contact-form-email,.contact-form-email-message{width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:10px;font:inherit;font-size:15px;margin:4px 0 10px;max-width:100%}
.contact-form-button-submit{background:var(--teal);color:#fff;border:0;border-radius:10px;padding:10px 18px;font-weight:600;cursor:pointer;height:auto}
.about-box p{margin:0;color:#4b5563;font-size:15px}

/* Footer */
.site-footer{background:var(--navy);color:#a9bbd1;padding:40px 0;font-size:14px;margin-top:20px}
.site-footer .wrap{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;align-items:center}
.site-footer a{color:#fff}
.site-footer .PageList ul{list-style:none;margin:0;padding:0;display:flex;gap:18px;flex-wrap:wrap}
.site-footer .widget-title,.site-footer h3.title{display:none}

@media(max-width:640px){
body{font-size:16px}
.site-header{position:static}
.site-header .wrap{padding-top:12px;padding-bottom:12px}
.site-nav .PageList li a{padding:6px 10px;font-size:14px}
.hero{padding:44px 0 50px}
.is-multiple .blog-posts{grid-template-columns:1fr}
.main-wrap{padding:28px 16px}
.post-body{font-size:17px}
}
